struct Fact { owner:array<float>, completed:float }
struct Parser { functions:List<Fact> }
fn update(p:Parser,index:int,checked:int)->void {
 let f:Fact=(list_Fact_get p.functions index)
 (list_Fact_set p.functions index Fact {owner:f.owner,completed:(cond ((and (== checked 1) (== (array_length f.owner) 1)) (at f.owner 0)) (else 0.0))})
}
shadow update { assert true }
fn main()->int {
 let functions:List<Fact> =(list_Fact_new)
 (list_Fact_push functions Fact {owner:[7.5],completed:0.0})
 (update Parser{functions:functions} 0 1)
 assert (== (list_Fact_get functions 0).completed 7.5)
 return 0
}
shadow main { assert true }

